// Candidate component: all acceptance comparisons consume actual current data.
// Historical expected objects are only forward-composed; actual entries are never downgraded.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
export const algorithmSha=x=>createHash('sha256').update(x).digest('hex');
export const algorithmCanon=x=>JSON.stringify((function sort(v){if(Array.isArray(v))return v.map(sort);if(v&&typeof v==='object')return Object.fromEntries(Object.keys(v).sort().map(k=>[k,sort(v[k])]));return v;})(x));
const read=name=>JSON.parse(fs.readFileSync(new URL(name,import.meta.url),'utf8'));
export const algorithmProof=read('./component.json'),algorithmRecords=algorithmProof.records,algorithmAssets=read('./asset-manifest.json'),algorithmOwnership=read('./ownership-map.json');
const p=algorithmProof,get=(o,keys)=>keys.reduce((v,k)=>v[k],o),set=(o,keys,v)=>keys.slice(0,-1).reduce((v,k)=>v[k],o)[keys.at(-1)]=v,key=r=>JSON.stringify([r.entryId,r.path]);
const pins={"component.json": "5c0922960781238ab0f77911fe50a0db311fe66fe9de0d9264ebb71d198e81e5", "asset-manifest.json": "adc966bd9891e4fc8a4a8850fc589b2fb12680f20fe4dfb29d6a0bc0dd9b4f33", "ownership-map.json": "6cb03c8ac185b512efba52de1bb17ddeb00b37996d273e1567cbe8d564fb35bc"};
for(const [name,hash]of Object.entries(pins))assert.equal(algorithmSha(fs.readFileSync(new URL(name,import.meta.url))),hash,'immutable reviewed algorithm input '+name);
assert.equal(p.records.length,18);assert.equal(new Set(p.records.map(key)).size,18);assert.equal(Object.keys(p.beforeEntries).length,15);assert.equal(p.current541EntryOrder.length,803);assert.equal(new Set(p.current541EntryOrder).size,803);
const forward=structuredClone(p.beforeEntries),reverse=structuredClone(p.afterEntries);
for(const r of p.records){for(const side of ['before','after'])assert.equal(algorithmSha(r[side]),r[side+'Sha256']);assert.equal(get(forward[r.entryId],r.path),r.before);set(forward[r.entryId],r.path,r.after);assert.equal(get(reverse[r.entryId],r.path),r.after);set(reverse[r.entryId],r.path,r.before);let next=r.before;for(const s of p.splices.filter(s=>key(s)===key(r))){if(Object.hasOwn(s,'append'))next+=s.append;else{assert.equal(next.split(s.old).length,2,'unique exact splice');next=next.replace(s.old,s.new);}}assert.equal(next,r.after,'complete leaf reconstructed from only exact approved splices');}
assert.deepEqual(forward,p.afterEntries);assert.deepEqual(reverse,p.beforeEntries);
for(const id of Object.keys(p.beforeEntries)){assert.equal(algorithmSha(algorithmCanon(p.beforeEntries[id])),p.beforeCanonicalHashes[id]);assert.equal(algorithmSha(algorithmCanon(p.afterEntries[id])),p.afterCanonicalHashes[id]);assert.equal(p.beforeCanonicalHashes[id],p.current541CanonicalHashes[id]);}
assert.equal(p.registryRecords.length,18);assert.equal(p.registryRecords.filter(r=>r.action==='compose').length,1);assert.equal(p.registryRecords.filter(r=>r.action==='append').length,17);
for(const t of p.registryRecords){const r=p.records.find(r=>key(r)===key(t.after));assert.ok(r);for(const field of ['entryId','path','after','afterSha256'])assert.deepEqual(t.after[field],r[field]);if(t.action==='compose'){assert.equal(t.index,11);assert.equal(t.before.after,r.before);assert.equal(t.before.afterSha256,r.beforeSha256);assert.deepEqual(t.after,{...t.before,after:r.after,afterSha256:r.afterSha256});}else{assert.equal(t.before,null);assert.equal(t.after.before,r.before);assert.equal(t.after.beforeSha256,r.beforeSha256);}}
export function algorithmEntry(expected541){if(!Object.hasOwn(p.beforeEntries,expected541.id))return structuredClone(expected541);assert.deepEqual(expected541,p.beforeEntries[expected541.id],'exact whole541 expected entry before algorithm composition');return structuredClone(p.afterEntries[expected541.id]);}
export function algorithmEntryHash(id,hash541){if(!Object.hasOwn(p.beforeEntries,id))return hash541;assert.equal(hash541,p.beforeCanonicalHashes[id],'exact541 expected hash before algorithm composition '+id);return p.afterCanonicalHashes[id];}
export function assertAlgorithmAffected(actual){const E=actual instanceof Map?actual:new Map(actual.map(e=>[e.id,e]));assert.equal(E.size,803,'complete actual corpus required');for(const [id,expected]of Object.entries(p.afterEntries))assert.deepEqual(E.get(id),expected,'entire current algorithm entry '+id);for(const[id,h]of Object.entries(p.unaffectedEntryHashes))assert.equal(algorithmSha(algorithmCanon(E.get(id))),h,'current unrelated algorithm must stay exact '+id);for(const r of p.unchangedLeafHashes)assert.equal(algorithmSha(get(E.get(r.entryId),r.path)),r.sha256,'existing current code unchanged '+r.entryId);return{leaves:18,entries:15};}
export function assertAlgorithmRegistryRows(actual){assert.equal(actual.records.length,558);assert.equal(new Set(actual.records.map(key)).size,558);for(const t of p.registryRecords)assert.deepEqual(actual.records[t.index],t.after,'entire composed/appended algorithm registry record '+t.index);return 18;}
export const decodeAlgorithmHtml=s=>s.replace(/&(amp|lt|gt|quot|apos|#39|#x27);/g,(_,x)=>({amp:'&',lt:'<',gt:'>',quot:'"',apos:"'",'#39':"'",'#x27':"'"}[x])).replace(/&#(\d+);/g,(_,n)=>String.fromCodePoint(+n));
export function algorithmJavaBlocks(html){return [...html.matchAll(/<pre\b[^>]*>([\s\S]*?)<\/pre>/g)].map(m=>decodeAlgorithmHtml(m[1].replace(/^<code\b[^>]*>|<\/code>$/g,'')));}
export function assertAlgorithmAssetRoot(assetRoot){assert.equal(algorithmAssets.assets.length,17);assert.equal(algorithmAssets.assets.filter(a=>a.path.endsWith('.java')).length,16);for(const a of algorithmAssets.assets){const file=path.join(assetRoot,a.path),bytes=fs.readFileSync(file);assert.equal(bytes.length,a.bytes);assert.equal(algorithmSha(bytes),a.sha256,'exact current runnable asset '+a.path);}const folder=path.join(assetRoot,'assets/examples/algorithm-shared');assert.deepEqual(fs.readdirSync(folder).sort(),algorithmAssets.assets.map(a=>path.basename(a.path)).sort(),'no old full source or unreviewed dependency shipped');return 17;}
export function assertAlgorithmAssets(site){assertAlgorithmAssetRoot(path.join(site,'public'));assertAlgorithmAssetRoot(path.join(site,'dist'));return 17;}
export function assertAlgorithmOwnership(actual,assetRoot){const E=actual instanceof Map?actual:new Map(actual.map(e=>[e.id,e])),source=name=>fs.readFileSync(path.join(assetRoot,'assets/examples/algorithm-shared',name),'utf8');for(const row of algorithmOwnership.members){assert.equal(algorithmSha(row.member),row.sha256);assert.ok(source(row.file).includes(row.member));assert.ok(algorithmJavaBlocks(get(E.get(row.entryId),row.path)).some(s=>s.includes(row.member)),'complete current member at exact owner '+row.marker);}
 for(const row of algorithmOwnership.proseMoves){assert.equal(algorithmSha(row.html),row.sha256);assert.ok(p.beforeEntries[row.fromEntryId].supplementHtml.includes(row.html));assert.ok(E.get(row.toEntryId).supplementHtml.includes(row.html),'independent boundary prose preserved '+row.toEntryId);}
 for(const row of p.sourceProvenance){const file=path.basename(row.file),src=source(file);assert.equal(algorithmSha(src),row.afterSha256);if(row.sourceEntryId){const original=p.beforeEntries[row.sourceEntryId];assert.ok(original,'complete current source entry pinned');const blocks=algorithmJavaBlocks(get(original,row.sourcePath));assert.equal(blocks[row.sourcePreIndex],src,'full shared source exactly current pre-relocation bytes '+file);}}
 const recent=algorithmOwnership.recentMarker;let total=0;for(const e of E.values())for(const b of algorithmJavaBlocks(e.supplementHtml??'')){const count=b.split(recent).length-1;if(count){assert.equal(e.id,'handwrite-47','RecentPlayers complete member under bounded-recency/LRU owner');total+=count;}}assert.equal(total,1);for(const id of ['155','215'])assert.ok(E.get(id).supplementHtml.includes('#/e/handwrite-47'));
 assert.ok(!E.get('p-list').supplementHtml.includes('public class CodingBoundaryExtras'));assert.ok(!E.get('155').supplementHtml.includes('public class InterviewCaches'));
 const array=source('ArrayMissing.java');for(const bad of algorithmOwnership.noLegacyArrayMethods)assert.ok(!array.includes(bad));for(const[eid,method,label]of [['p-array','longestSquareSubstring','xx'],['253','weightedMeetings','weighted']]){const snippet=algorithmJavaBlocks(E.get(eid).supplementHtml).find(s=>s.includes(method+'('));assert.ok(snippet);assert.equal(algorithmSha(snippet),algorithmOwnership.sourceArraySnippets[label]);assert.ok(array.includes(snippet));}
 const normalize=s=>s.replace(/^import [^;]+;\s*/gm,'').replace(/\bstatic class LFUCache\b/,'class LFUCache').replace(/java\.util\./g,'').trim();assert.equal(normalize(E.get('p-design').templates[1].java),normalize(E.get('460').code));assert.equal(source('LFUCache.java'),E.get('460').code);assert.ok(source('InterviewCaches.java').includes('buckets.remove(e.frequency);'),'current empty-bucket deletion retained');
 for(const r of p.records){const text=get(E.get(r.entryId),r.path);for(const m of text.matchAll(/href="#\/e\/([^"/]+)(?:\/([^"/]+))?"/g)){assert.ok(E.has(m[1]),'entry link exists '+m[1]);if(m[2])assert.ok(E.get(m[1]).items?.some((q,i)=>(q.id??String(i))===m[2]));}for(const m of text.matchAll(/href="(assets\/examples\/algorithm-shared\/[^"#?]+)"/g))assert.ok(algorithmAssets.assets.some(a=>a.path===m[1]),'download link exactly shipped '+m[1]);}
 const narrow=p.records.find(r=>r.entryId==='p-array'&&r.path.join('.')==='templates.1.java'),strip=s=>s.replace(/\/\*[\s\S]*?\*\//g,'').replace(/\/\/[^\n]*/g,'').trim();assert.equal(strip(narrow.before),strip(narrow.after),'spiral correction changes comments only');return{members:algorithmOwnership.members.length,proseMoves:algorithmOwnership.proseMoves.length,recentPlayersOwners:1,assets:17};}
